function manifestSnapshot() {
  const files = {};
  for (const rel of common.walk('.').filter(isManifest)) {
    try {
      files[rel] = sha256(fs.readFileSync(common.absPath(rel)));
    } catch {
      // removed while the snapshot was taken
    }
  }
  return files;
}

// Manifest changes since the recorded state; null when there is no Git directory to keep state in.
function manifestChanges() {
  let file;
  try {
    file = common.stateFile(MANIFEST_STATE);
  } catch {
    return null;
  }
  const before = readManifestState(file);
  const after = manifestSnapshot();
  const save = () => writeManifestState(file, after);
  if (!before) return { initial: true, changed: Object.keys(after).sort(), added: [], removed: [], moved: [], save };
  const changed = Object.keys(after).filter((f) => before[f] !== after[f]).sort();
  const gone = Object.keys(before).filter((f) => !(f in after)).sort();
  const added = changed.filter((f) => !(f in before));
  const moved = [];
  for (const from of gone) {
    const to = added.find((f) => after[f] === before[from] && !moved.some(([, t]) => t === f));
    if (to) moved.push([from, to]);
  }
  const removed = gone.filter((f) => !moved.some(([m]) => m === f));
  return { initial: false, changed, added, removed, moved, save: changed.length || gone.length ? save : () => {} };

function changeNotes(delta, recognized) {
  const movedTo = new Set(delta.moved.map(([, to]) => to));
  const candidates = recognized ? [] : delta.changed.filter((f) => !movedTo.has(f));
  const uncommitted = new Set(candidates.length ? common.changedFiles(candidates) : []);
  const lines = [
    ...candidates.filter((f) => uncommitted.has(f)).map((f) => `${delta.added.includes(f) ? 'added' : 'modified'}: ${f}`),
    ...delta.removed.map((f) => `removed: ${f}`),
    ...delta.moved.map(([from, to]) => `moved: ${from} -> ${to}`),
  ];
  if (!lines.length) return [];
  return [
    recognized
      ? 'Dependency manifests or project files removed or moved:'
      : 'Dependency manifests or project files changed without a recognized dependency or project-reference command:',
    ...limit(lines.map((l) => `- ${l}`)),
    'Confirm the owning workflow was applied: dependency entries, add-dependency (.claude/skills/add-dependency/SKILL.md); projects and project references, project-structure (.claude/skills/project-structure/SKILL.md). A branch switch or another change of the checked-out revision needs no workflow.',
  ];

try {
  const input = common.readStdinJson();
  const event = input.hook_event_name || 'PostToolUse';
  const cwd = input.cwd || process.cwd();
  common.useActiveRoot(cwd);
  const tool = input.tool_name || '';
  const toolInput = input.tool_input || {};
  let messages = [];
  if (['Write', 'Edit', 'MultiEdit'].includes(tool)) {
    const rel = common.relativeInsideRoot(toolInput.file_path, cwd);
    if (rel) {
      messages = fileChecks(rel, changedText(toolInput));
      if (isManifest(rel)) recordManifestEdit(rel);
    }
  } else if (['Bash', 'PowerShell'].includes(tool)) {
    messages = shellChecks(toolInput.command, tool);
  }
  if (messages.length && event === 'PostToolUseFailure') out.addContext(event, messages.join('\n'));
  if (messages.length) out.block(messages.join('\n'));
  out.allow();
} catch (e) {
  out.fail('post-tool-use', e, 'post-change checks were not applied');

  const input = readStdinJson();
  if (typeof input.tool_name !== 'string') throw new Error('hook input has no tool_name');
  const tool = input.tool_name;
  if (['Bash', 'PowerShell'].includes(tool)) {
    const result = analyzeCommand(input.tool_input && input.tool_input.command, tool);
    if (result.block) out.denyToolUse(result.message);
  }
  out.allow();
} catch (e) {
  if (out) out.denyOnFailure('pre-tool-use', e, 'dependency and project-reference routing could not be applied');
  process.stderr.write(`pre-tool-use hook failed (${e && e.message ? e.message : e}); the command was blocked.\n`);
  process.exit(2);

if (coChange) {
  const model = files.filter((f) => common.matchesAny(f, coChange.model));
  if (model.length) {
    const companions = Object.entries(coChange.companions || {});
    const missing = companions.filter(([, globs]) => !files.some((f) => common.matchesAny(f, globs))).map(([name]) => name);
    if (missing.length) {
      messages.push(`Persistence model files changed (${model.slice(0, 3).join(', ')}${model.length > 3 ? ', ...' : ''}) without ${missing.join(' or ')} changes: confirm the persistence-change workflow was applied (${coChange.owner}).`);
      model.forEach((f) => inputs.add(f));
      files.filter((f) => companions.some(([, globs]) => common.matchesAny(f, globs))).forEach((f) => inputs.add(f));
    }
  }
}
const frame = common.moduleFor(modules, 'architecture');
const testSuffixes = ((frame && frame.manifest.enforcement.architecture.testProjects) || []).map((t) => t.suffix);
const isTest = (f) => testSuffixes.some((s) => f.split('/').some((seg) => seg.endsWith(s))) || /Tests\//.test(f);
const backendCode = files.filter((f) => f.startsWith('backend/') && f.endsWith('.cs'));
if (backendCode.some((f) => !isTest(f)) && !backendCode.some(isTest)) {
  messages.push('Backend production code changed without test changes: check regression coverage and behavioral-probe preservation (development-workflow, verify).');
  backendCode.forEach((f) => inputs.add(f));

try {
  const input = common.readStdinJson();
  if (input.stop_hook_active) hook.allow();
  common.useActiveRoot(input.cwd || process.cwd());
  const files = common.changedFiles();
  if (!files.length) hook.allow();
  const { messages, inputs } = reminders(files);
  if (!messages.length) hook.allow();
  const fingerprint = sha256(JSON.stringify({ messages, state: inputs.map((f) => [f, contentIdentity(f)]) }));
  const file = common.stateFile('claude-stop-check.json');
  let state = {};
  try {
    state = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    state = {};
  }
  if (state.fingerprint === fingerprint) hook.allow();
  try {
    fs.writeFileSync(file, JSON.stringify({ fingerprint }), 'utf8');
  } catch {
    // Without stored state the reminder may repeat on a later stop; stop_hook_active still prevents a loop.
  }
  hook.block(`Co-change check:\n- ${messages.join('\n- ')}\nAddress these or state why they do not apply, then finish.`);

function denyOnFailure(hookName, error, consequence) {
  denyToolUse(
    `${hookName} hook failed (${errorText(error)}); ${consequence}, so the command was blocked.\n` +
      'Report the hook failure to the user; the instruction system is repaired through the template-maintenance workflow.\n'
  );

