// single- or double-quoted; a start tag that cannot be read has attrs null, and reading resumes
// after its next '>'.
function readTag(xml, i) {
  const close = xml[i + 1] === '/';
  XML_NAME.lastIndex = i + (close ? 2 : 1);
  const name = (XML_NAME.exec(xml) || [])[0];
  if (!name) return null;
